solution.code:
public class Main {
    public static void main(String[] args) {
        Manager m = new Manager("Asha", 1000, 500);
        System.out.println(m.name + " earns " + m.yearly());
    }
}

class Employee {
    protected String name;
    protected int salary;

    Employee(String name, int salary) {
        this.name = name;
        this.salary = salary;
    }
}

class Manager extends Employee {
    private int bonus;

    Manager(String name, int salary, int bonus) {
        super(name, salary);
        this.bonus = bonus;
    }

    int yearly() {
        return salary * 12 + bonus;
    }
}
